import{_ as e,c as a,a2 as p,o}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第一百六十一章 不被渔夫钓上岸","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/161第一百六十一章 不被渔夫钓上岸.md","filePath":"meditation/巴利文大藏经/161第一百六十一章 不被渔夫钓上岸.md"}'),_={name:"meditation/巴利文大藏经/161第一百六十一章 不被渔夫钓上岸.md"};function r(n,t,i,s,d,c){return o(),a("div",null,t[0]||(t[0]=[p('<h1 id="第一百六十一章-不被渔夫钓上岸" tabindex="-1">第一百六十一章 不被渔夫钓上岸 <a class="header-anchor" href="#第一百六十一章-不被渔夫钓上岸" aria-label="Permalink to &quot;第一百六十一章 不被渔夫钓上岸&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部17相应2经/钓钩经(利得恭敬相应/因缘篇/如来记说)</p><p>有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，佛陀对出家弟子们说：“弟子们，世间人丰厚的供养，富贵舒适的生活，世间人虔诚的尊敬、恭敬，家喻户晓的名誉声望，这些是让人内心颤抖恐怖的，这些是让人内心激烈搅动的，这些是让人内心暴躁不安的，这些是修行人内心达到清净安稳的障碍，这些是修行人内心挣脱束缚捆绑的阻碍。</p><p>弟子们，就如同有一个渔夫他在深水的湖泊中钓鱼，他向湖泊中投入带饵料的鱼钩，如果湖泊里面有鱼贪吃渔夫鱼钩上的饵料，那么这条鱼就会被渔夫钓起来。弟子们，这条被渔夫钓起来的鱼就会被渔夫抓住，它就会遭遇不幸和灾祸，渔夫可以对它为所欲为，或者将它吃掉，或者将它卖掉。</p><p>弟子们，这是一个比喻，渔夫比喻的就是欲望，这个欲望也可以说成是世间人经常谈到的魔王波旬，弟子们，你们要明白所谓的魔王波旬就是自己的欲望，而不是那些装神弄鬼的世间人创造出来的有大神通的魔王，那些都是他们自己胡编乱造出来诈骗钱财的谎言。魔王波旬就是自己内心的欲望。鱼钩上的饵料比喻的就是世间人丰厚的供养，富贵舒适的生活，世间人虔诚的尊敬、恭敬，家喻户晓的名誉声望。弟子们，世间任何的修行人，如果他们喜欢、贪求世间人丰厚的供养，喜欢、贪求富贵舒适的生活，喜欢、贪求世间人虔诚的尊敬、恭敬，喜欢、贪求家喻户晓的名誉声望，那么他们就会被魔王波旬的钓钩钓起来，也就是他们会被欲望的钓钩钓起来；任何的修行人如果他们沉浸、陶醉、沉溺在世间人丰厚的供养，富贵舒适的生活，世间人虔诚的尊敬、恭敬，家喻户晓的名誉声望之中，那么他们就会被魔王波旬的钓钩钓起来，也就是他们会被欲望的钓钩钓起来；弟子们，这些被魔王波旬钓钩钓起来的修行人，这些被欲望钓起来的修行人，他们就会遭遇不幸和灾祸，魔王波旬会对他们为所欲为，欲望会对他们为所欲为，他们将会被魔王波旬控制，他们将会被欲望控制，他们将会被喜怒哀乐等等内心生起的念想诱惑、吸引、奴役、折磨、拷打。他们将会最终产生忧愁、悲伤、苦闷、忧虑、绝望等等无数多的烦恼和痛苦，就算他们产生了快乐和喜悦也是短暂的，因为世间一切的事物随时都是在变化的，无法永恒保持不变，无法永远的存在，一旦他们失去自己喜欢的事物，或者他们喜欢的事物衰败、灭亡、消失的时候，他们就会产生烦恼和痛苦。</p><p>弟子们，世间人丰厚的供养，富贵舒适的生活，世间人虔诚的尊敬、恭敬，家喻户晓的名誉声望就是这样的让人内心颤抖恐怖，就是这样的让人内心激烈搅动，就是这样的让人内心暴躁不安。</p><p>世间人丰厚的供养，富贵舒适的生活，世间人虔诚的尊敬、恭敬，家喻户晓的名誉声望是修行人内心达到清净安稳的障碍，是修行人内心挣脱束缚捆绑的阻碍。弟子们，因此，你们应该这样去修行：「我们要舍离、放弃已经获得的丰厚供养，我们要舍离、放弃已经获得的富贵舒适的生活，我们要舍离、放弃已经获得的世间人虔诚的尊敬、恭敬，我们要舍离、放弃已经获得的家喻户晓的名誉声望。而且我们不要执着和挂念这些已经获得的丰厚供养，不要执着和挂念这些已经获得的富贵舒适的生活，不要执着和挂念这些已经获得的世间人虔诚的尊敬、恭敬，不要执着和挂念这些已经获得的家喻户晓的名誉声望。我们不要让丰厚供养，富贵舒适的生活，世间人虔诚的尊敬、恭敬，家喻户晓的名誉声望扰乱我们的内心；不要让丰厚供养，富贵舒适的生活，世间人虔诚的尊敬、恭敬，家喻户晓的名誉声望让我们胡思乱想、内心散乱。」弟子们，你们就应该这样的去修行。”</p><p>佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。</p>',9)]))}const f=e(_,[["render",r]]);export{m as __pageData,f as default};
